samples={'py':'# hi\ndef f(x):\n    s = "ok"\n    return x + 1\n','go':'package main\nfunc main() { println("hi") }\n','json':'{"a": 1, "b": true}\n','html':'<b>x</b>\n','plain':'x=1\n','pkg':'package main\n'}
for name,text in samples.items():
 print('---',name)
 lx = {'py':PythonLexer(),'go':GoLexer(),'json':JsonLexer(),'html':HtmlLexer()}.get(name)
 if lx is None:
  try: lx=guess_lexer(text); print('guess', lx)
  except Exception as e: print('guess err',e); continue
 for t,v in lex(text,lx):
  print(str(t),repr(v))
